/*
 * E-ZERO Secure Pair V1 — atomic WebAuthn REGISTRATION storage LAB.
 *
 * Browser- and Worker-UNREACHABLE; no public API imports this module.
 * Requires a PRE-VERIFIED account record provisioned by a separate trusted
 * account-enrolment authority (not yet implemented). This class deliberately
 * has NO account bootstrap, session-cookie issuance, Trusted Device activation,
 * bearer capability or ECU operation.
 *
 * Each registration challenge is generated by vetted SimpleWebAuthn and its
 * SHA-256 digest is stored in durable SQLite. A vetted verification result is
 * applied ONLY inside a single transaction that: checks account status and
 * version, inserts the unique COSE key, consumes the challenge, and bumps the
 * account version. Any failure rolls back ALL writes. No client "verified"
 * boolean or private biometrics are used.
 *
 * Same DO instance/storage must hold account, credential and pending tables.
 */
import {makeRegistrationOptionsLab,verifyRegistrationResponseLab}
 from "./webauthn_registration_library_lab_v0_1.mjs";
import {PAIR_V1_RP_ID} from "./pair_policy_v1.mjs";
const A=/^[A-Za-z0-9_-]{12,64}$/;
const SID=/^[a-f0-9]{32}$/;
const B64=/^[A-Za-z0-9_-]+$/;
const TTL=90_000;
const encoder=new TextEncoder();
const out=(ok,code,extra={})=>Object.freeze({
 ok,code,authorized:false,accountSessionIssued:false,
 trustedDeviceActivated:false,...extra
});
const hex=v=>[...v].map(b=>b.toString(16).padStart(2,"0")).join("");
function encode(bytes){
 let s="";for(const b of bytes)s+=String.fromCharCode(b);
 return btoa(s).replace(/\+/g,"-").replace(/\//g,"_").replace(/=+$/,"");
}
function decode(input,max){
 if(typeof input!=="string"||!B64.test(input)||input.length>max*2)
  throw Error("INVALID_ENCODING");
 const raw=atob(input.replace(/-/g,"+").replace(/_/g,"/")+
  "=".repeat((4-input.length%4)%4));
 if(raw.length<1||raw.length>max)throw Error("INVALID_ENCODING");
 const bytes=Uint8Array.from(raw,c=>c.charCodeAt(0));
 if(encode(bytes)!==input)throw Error("INVALID_ENCODING");
 return bytes;
}
async function digestChallenge(challenge){
 const b=decode(challenge,32);
 if(b.length!==32)throw Error("INVALID_CHALLENGE");
 return hex(new Uint8Array(await crypto.subtle.digest("SHA-256",
  encoder.encode(challenge))));
}
function checkAccount(row){
 if(!row||row.status!=="PREVERIFIED_LAB_ONLY"||
    !A.test(row.account_id||"")||
    !Number.isSafeInteger(row.version)||row.version<1)
  return null;
 try{
  const h=decode(row.user_handle,64);
  if(h.length<16)return null;
  return {accountId:row.account_id,userHandle:h,version:row.version};
 }catch(_){return null;}
}
function pendingValid(row,now){
 return row&&row.purpose==="WEBAUTHN_REGISTER"&&
  row.consumed_at===null&&Number.isSafeInteger(row.issued)&&
  Number.isSafeInteger(row.expires)&&row.issued>0&&row.issued<=now&&
  row.expires>now&&row.expires>row.issued&&row.expires-row.issued<=TTL;
}
export class PairV1SqliteAtomicPasskeyRegistrationLab{
 #sql;#tx;
 constructor(storage){
  if(typeof storage?.sql?.exec!=="function"||
     typeof storage?.transactionSync!=="function")
   throw Error("SQLITE_TRANSACTION_REQUIRED");
  this.#sql=storage.sql;this.#tx=storage.transactionSync.bind(storage);
  // Account rows may only be provisioned by a future independently audited
  // owner-verification path. CI fixtures inject such a row directly; there
  // is intentionally no method to create a PREVERIFIED account.
  this.#sql.exec(`CREATE TABLE IF NOT EXISTS ezero_v1_auth_accounts_lab (
   account_id TEXT PRIMARY KEY,
   user_handle TEXT NOT NULL UNIQUE,
   status TEXT NOT NULL CHECK(status IN('PREVERIFIED_LAB_ONLY','REVOKED')),
   version INTEGER NOT NULL DEFAULT 1
  )`);
  // Shared with PairV1SqliteAtomicPasskeyFinishLab: exact storage schema.
  this.#sql.exec(`CREATE TABLE IF NOT EXISTS ezero_v1_auth_credentials_lab (
   account_id TEXT NOT NULL,
   credential_id TEXT PRIMARY KEY,
   cose_public_key TEXT NOT NULL,
   sign_count INTEGER NOT NULL CHECK(sign_count>=0),
   alg INTEGER NOT NULL CHECK(alg=-7),
   rp_id TEXT NOT NULL,
   transports_json TEXT NOT NULL DEFAULT '[]',
   status TEXT NOT NULL CHECK(status IN ('ACTIVE','REVOKED')),
   revoked INTEGER NOT NULL DEFAULT 0 CHECK(revoked IN(0,1)),
   version INTEGER NOT NULL DEFAULT 1
  )`);
  this.#sql.exec(`CREATE TABLE IF NOT EXISTS ezero_v1_register_pending_lab (
   session_id TEXT PRIMARY KEY,
   challenge_digest TEXT NOT NULL UNIQUE,
   account_id TEXT NOT NULL,
   account_version INTEGER NOT NULL,
   issued INTEGER NOT NULL,
   expires INTEGER NOT NULL,
   purpose TEXT NOT NULL CHECK(purpose='WEBAUTHN_REGISTER'),
   consumed_at INTEGER
  )`);
 }
 #account(id){
  return checkAccount(this.#sql.exec(
   "SELECT * FROM ezero_v1_auth_accounts_lab WHERE account_id=?",id
  ).toArray()[0]);
 }
 async begin({accountId}={},now=Date.now()){
  if(!A.test(accountId||"")||!Number.isSafeInteger(now)||now<=0)
   return out(false,"ACCOUNT_CONTEXT_INVALID");
  let account,existing;
  try{
   account=this.#account(accountId);
   if(!account)return out(false,"PREVERIFIED_ACCOUNT_REQUIRED");
   existing=this.#sql.exec(`SELECT credential_id
    FROM ezero_v1_auth_credentials_lab WHERE account_id=?
    ORDER BY credential_id LIMIT 26`,accountId).toArray();
   if(existing.length>25)return out(false,"CREDENTIAL_LIMIT_REACHED");
  }catch(_){return out(false,"ACCOUNT_REGISTRY_UNAVAILABLE");}
  const generated=await makeRegistrationOptionsLab({
   accountId,userHandle:account.userHandle,
   existingCredentialIds:existing.map(row=>row.credential_id),now
  });
  if(!generated.ok)return out(false,generated.code);
  const sessionId=hex(crypto.getRandomValues(new Uint8Array(16)));
  let digest;
  try{digest=await digestChallenge(generated.options.challenge);}
  catch(_){return out(false,"SERVER_CHALLENGE_INVALID");}
  try{
   this.#tx(()=>{
    const current=this.#account(accountId);
    if(!current||current.version!==account.version)
     throw Error("ACCOUNT_CHANGED");
    this.#sql.exec(`INSERT INTO ezero_v1_register_pending_lab
     (session_id,challenge_digest,account_id,account_version,issued,expires,purpose)
     VALUES(?,?,?,?,?,?,'WEBAUTHN_REGISTER')`,
     sessionId,digest,accountId,account.version,now,now+TTL);
   });
  }catch(_){return out(false,"REGISTRATION_LEDGER_UNAVAILABLE");}
  return out(true,"REGISTRATION_CHALLENGE_STORED_LAB",{
   sessionId,expires:now+TTL,options:generated.options,
   challengeConsumed:false,credentialPersisted:false
  });
 }
 async finish({accountId,sessionId,response}={},now=Date.now()){
  if(!A.test(accountId||"")||!SID.test(sessionId||"")||
     !Number.isSafeInteger(now)||now<=0||!response||
     response.type!=="public-key"||
     typeof response.id!=="string"||response.id.length>256)
   return out(false,"REGISTRATION_CONTEXT_INVALID");
  let row,account;
  try{
   row=this.#sql.exec(`SELECT * FROM ezero_v1_register_pending_lab
     WHERE session_id=? AND account_id=?`,sessionId,accountId).toArray()[0];
   account=this.#account(accountId);
   if(!account||!pendingValid(row,now)||
      row.account_version!==account.version)
    return out(false,"REGISTRATION_EXPIRED_REPLAYED_OR_UNBOUND");
  }catch(_){return out(false,"REGISTRATION_LEDGER_UNAVAILABLE");}
  let challenge;
  try{
   const b64=response.response?.clientDataJSON;
   const data=decode(b64,4096);
   const client=JSON.parse(new TextDecoder("utf-8",{fatal:true}).decode(data));
   challenge=client?.challenge;
   if(await digestChallenge(challenge)!==row.challenge_digest)
    return out(false,"CHALLENGE_MISMATCH");
  }catch(_){return out(false,"INVALID_REGISTRATION_CLIENT_DATA");}
  const verified=await verifyRegistrationResponseLab({
   response,pending:{
    accountId,challenge,purpose:"WEBAUTHN_REGISTER",consumed:false,
    issued:row.issued,expires:row.expires
   },serverAccountId:accountId,now
  });
  if(!verified.ok)return out(false,verified.code);
  const id=verified.credentialId;
  const key=verified.publicKeyCose;
  const counter=verified.counter;
  if(typeof id!=="string"||!B64.test(id)||id.length<16||
     id.length>256||!(key instanceof Uint8Array)||key.length<32||
     key.length>512||!Number.isSafeInteger(counter)||counter<0||
     counter>0xffffffff)
   return out(false,"VERIFIED_CREDENTIAL_INVALID");
  // Transports supplied by the client are only UX hints, never device proof.
  const transports=response.response?.transports;
  const validated=Array.isArray(transports)&&transports.length<=5&&
   transports.every(x=>["usb","nfc","ble","internal","hybrid"].includes(x))?
   transports:[];
  try{
   return this.#tx(()=>{
    const current=this.#account(accountId);
    if(!current||current.version!==account.version)
     throw Error("ACCOUNT_CHANGED");
    // Transaction covers credential insert, one-use challenge and account
    // version bump; SQLite failures rollback ALL THREE atomically.
    this.#sql.exec(`INSERT INTO ezero_v1_auth_credentials_lab
      (account_id,credential_id,cose_public_key,sign_count,alg,rp_id,
       transports_json,status,revoked,version)
      VALUES(?,?,?,?,?,?,?,'ACTIVE',0,1)`,
      accountId,id,encode(key),counter,-7,PAIR_V1_RP_ID,
      JSON.stringify(validated));
    const consumed=this.#sql.exec(`UPDATE ezero_v1_register_pending_lab
      SET consumed_at=? WHERE session_id=? AND account_id=?
      AND account_version=? AND challenge_digest=?
      AND purpose='WEBAUTHN_REGISTER' AND consumed_at IS NULL
      AND issued<=? AND expires>?
      RETURNING session_id`,
      now,sessionId,accountId,account.version,row.challenge_digest,
      now,now).toArray();
    if(consumed.length!==1)throw Error("CHALLENGE_REPLAYED");
    const updated=this.#sql.exec(`UPDATE ezero_v1_auth_accounts_lab
      SET version=version+1
      WHERE account_id=? AND status='PREVERIFIED_LAB_ONLY'
      AND version=? RETURNING account_id`,
      accountId,account.version).toArray();
    if(updated.length!==1)throw Error("ACCOUNT_CHANGED");
    return out(true,"PASSKEY_REGISTERED_AND_CHALLENGE_CONSUMED_LAB",{
     credentialId:id,challengeConsumed:true,credentialPersisted:true,
     // Credential 'ACTIVE' means valid for WebAuthn signature verification
     // ONLY, not a Trusted Device, account login or remote-call privilege.
     verifiedPasskeyRecordOnly:true
    });
   });
  }catch(_){return out(false,"REGISTRATION_ATOMIC_COMMIT_REJECTED");}
 }
 // No CREATE ACCOUNT, no session issue, no Trusted Device activation.
}
